 loadMoreContent();
 }
 });

 function loadMoreContent() {
 fetch(`/loadMoreContent?page=${++page}`) 
 .then(response => response.text())
 .then(data => {
 document.getElementById('content-wrapper').insertAdjacentHTML('beforeend', data);
 loadAd();
 });
