```html
<script>
 function throttle(fn, wait) {
 let isCalled = false;
 return function(...args) {
 if (!isCalled) {
 fn.apply(this, args);
 isCalled = true;
 setTimeout(() => isCalled = false, wait);
 }
 };
 }

 const adClickHandler = throttle(() => {
 console.log("Ad clicked!");
 window.location.href = '/special-offer';
 }, 2000);

 const ctaButton = document.querySelector('.cta-button');
 ctaButton.addEventListener('click', adClickHandler);
</script>
```
This script includes a simple throttling function to ensure that the click event doesn't fire too rapidly, which is a common pattern in ad interactivity to improve user experience and prevent accidental multiple clicks.

